/** Valores de ATTRIBUTE TASKVALUE OF MYSELF que P005 reconoce. */
public enum FaseCaptacion {
    PREBATCH(1, "PREBATCH", 1, 6, true),
    PRELINEA(2, "PRELINEA", 2, 0, true),
    FINBATCH(3, "FINBATCH", 3, 0, true),
    GENERALOG(4, null, 0, 0, false),          // sin monitor
    REST24HRS(5, "REST24HRS", 5, 0, true),
    CARGA_CAT_P020(6, "CARGACATP020", 6, 0, true),
    INI_LINEA_P020(7, "INILINEAP020", 7, 0, true),
    INI_BATCH_P020(8, "INIBATCHP020", 8, 0, true),
    RECUP_BASE_ORIGINAL(10, null, 0, 0, false),
    RECUP_BASE_AUXILIAR(11, null, 0, 0, false),
    CREA_CTRL_ARRIBOS(20, null, 0, 0, false),
    AVISO_FIN_DIA(21, null, 0, 0, false),
    AVISO_INI_DIA(22, null, 0, 0, false),
    DEPURACION_ARCHIVOS(23, null, 0, 0, false),   // IBM-CHARITY
    BAJA_LINEA(24, null, 0, 0, false),
    INSTALA_L020(25, null, 0, 0, false),
    SUBE_LINEA(26, null, 0, 0, false),
    BAJA_ESCALONADA(50, null, 0, 0, false);

    final int taskValue; final String actividad; final int copiaMapli;
    final int inicioGrupo; final boolean monitor;

    FaseCaptacion(int tv, String act, int copia, int iniGpo, boolean mon) {
        taskValue = tv; actividad = act; copiaMapli = copia; inicioGrupo = iniGpo; monitor = mon;
    }

    static Optional<FaseCaptacion> of(int taskValue) {
        return Arrays.stream(values()).filter(f -> f.taskValue == taskValue).findFirst();
    }
}

@Component
@RequiredArgsConstructor
public class MonitorBatchListener implements JobExecutionListener {

    private final MonitorMapliClient mapli;   // S038L035 / 70000950-INI-PGM-MAPLI
    private final MonitorProperties props;    // grupo: 6, nombre: "BATCH DIARIO"

    @Override
    public void beforeJob(JobExecution job) {
        var fase = fase(job);
        if (!fase.monitor) return;                                   // W77-SI-MONITOR
        mapli.iniciaPrograma(props.grupo(), props.nombre(), fase.copiaMapli, fase.inicioGrupo);
        mapli.iniciaActividad(1, "PROCESO UNICO ");
    }

    @Override
    public void afterJob(JobExecution job) {
        if (!fase(job).monitor) return;
        mapli.registraAvance(1, job.getStepExecutions().stream()
                .mapToLong(StepExecution::getWriteCount).sum());      // 70000950-ACT-REGPROC
        mapli.finActividad(1);
        mapli.finPrograma();
    }
}

